"use strict";

// A SECOND, independently installed fixture-lib@1.0.0 -- same package
// name, same version, same exported shape as the top-level one, and a
// completely different install path. Nothing requires it.
//
// It exists so the PackageInstance identity control is a real test rather
// than a test against a path that does not exist: a resolution keyed on
// name-and-version rather than on install path would happily attribute
// THIS instance's export to the other instance's finding. See the
// "never substitutes a different PackageInstance" case in
// src/analysis/verdict.invocation-provenance-soundness.integration.test.ts.
function twin(input) {
  return "twin:" + input;
}

module.exports = twin;
